// One shared tooltip element for the whole interface. Content is always generated by the game code,
// never from remote data, so it is inserted as HTML for formatting but never from user input.

let tip: HTMLDivElement | null = null;
let showTimer = 0;
let hideTimer = 0;
let current: HTMLElement | null = null;
let lastX = 0;
let lastY = 0;

function element(): HTMLDivElement {
  if (!tip) {
    tip = document.createElement('div');
    tip.className = 'if-tip';
    tip.setAttribute('role', 'tooltip');
    document.body.appendChild(tip);
  }
  return tip;
}

function position(x: number, y: number): void {
  const node = element();
  const padding = 14;
  const rect = node.getBoundingClientRect();
  let left = x + 18;
  let top = y + 18;
  if (left + rect.width > window.innerWidth - padding) left = Math.max(padding, x - rect.width - 18);
  if (top + rect.height > window.innerHeight - padding) top = Math.max(padding, y - rect.height - 18);
  node.style.left = `${Math.round(left)}px`;
  node.style.top = `${Math.round(top)}px`;
}

export function showTip(content: string | HTMLElement, x: number, y: number): void {
  const node = element();
  node.replaceChildren(typeof content === 'string' ? content : content);
  if (typeof content === 'string') node.innerHTML = content;
  node.classList.add('is-visible');
  lastX = x;
  lastY = y;
  position(x, y);
}

export function hideTip(): void {
  window.clearTimeout(showTimer);
  window.clearTimeout(hideTimer);
  current = null;
  if (tip) tip.classList.remove('is-visible');
}

export function hideTipNow(): void {
  hideTip();
  if (tip) tip.classList.remove('is-visible');
}

/** Shows the tooltip for pointer-driven content such as the map province readout. */
export function showTipAt(content: string | HTMLElement, x: number, y: number): void {
  window.clearTimeout(showTimer);
  window.clearTimeout(hideTimer);
  showTip(content, x, y);
}

export function bindTip(target: HTMLElement, content: string | (() => string | HTMLElement)): void {
  const resolve = () => (typeof content === 'function' ? content() : content);

  target.addEventListener('pointerenter', (event) => {
    current = target;
    lastX = event.clientX;
    lastY = event.clientY;
    window.clearTimeout(hideTimer);
    window.clearTimeout(showTimer);
    showTimer = window.setTimeout(() => {
      if (current !== target) return;
      showTip(resolve(), lastX, lastY);
    }, 140);
  });

  target.addEventListener('pointermove', (event) => {
    lastX = event.clientX;
    lastY = event.clientY;
    if (tip?.classList.contains('is-visible') && current === target) position(lastX, lastY);
  });

  target.addEventListener('pointerleave', () => {
    if (current === target) hideTip();
  });

  target.addEventListener('focus', () => {
    current = target;
    const rect = target.getBoundingClientRect();
    window.clearTimeout(showTimer);
    showTimer = window.setTimeout(() => {
      if (current !== target) return;
      showTip(resolve(), rect.left + rect.width / 2, rect.bottom);
    }, 120);
  });

  target.addEventListener('blur', () => {
    if (current === target) hideTip();
  });
}
